package com.cctv.platform.storage;

import java.io.IOException;
import java.io.InputStream;

/**
 * Where footage, clips and thumbnails are kept (decision D7). Keys are generated by the API,
 * never taken from user input. {@link LocalVideoStorage} is used for development; an S3
 * implementation replaces it for deployment.
 */
public interface VideoStorage {

    /** Stores the stream under the key and returns the number of bytes written. */
    long store(String key, InputStream content) throws IOException;

    boolean exists(String key);

    /** Removes the object; does nothing if it is already gone. */
    void delete(String key) throws IOException;
}
